// Bossfrommars — move-classification icons.
// These are chess.com's own "Move Classification" badge artwork (the official
// icon set), embedded as inline PNG data URIs so nothing can block them:
// no network requests, no page-CSP issues, works in the panel and on the board.
(function () {
  // solid disc colour sampled from each official asset
  const COLOR = {
    brilliant: '#24afd8', great: '#547591', best: '#79ac45', excellent: '#78ab45',
    good: '#738d5c', book: '#d3a078', inaccuracy: '#f0bc2a', mistake: '#fe9e50',
    blunder: '#f03623', miss: '#f66f61', forced: '#8aa480', none: '#6f7e8a'
  };

  // the artwork, 64x64 (downscaled from the 98x98 originals)
  const DATA = {
    brilliant: '',
    great: '',
    best: '',
    excellent: '',
    good: '',
    book: '',
    inaccuracy: '',
    mistake: '',
    blunder: '',
    miss: '',
    forced: '',
  };

  // label -> data uri
  function color(key) { return COLOR[key] || COLOR.none; }
  function src(key) { return DATA[key] ? 'data:image/png;base64,' + DATA[key] : ''; }

  // <img> — panel, pop-up and move strip
  function img(key, cls) {
    if (!DATA[key]) return '';
    return '<img class="bfm-ic' + (cls ? ' ' + cls : '') + '" src="' + src(key) +
      '" alt="" draggable="false" decoding="async">';
  }

  // the badge as a standalone element
  function disc(key, cls) {
    return '<span class="bfm-disc" data-q="' + key + '" style="--q:' + color(key) + '">' +
      img(key) + '</span>';
  }

  // inside the board's own <svg>: <image> keeps it crisp at any size
  function boardBadge(key, cx, cy, size) {
    if (!DATA[key]) return '';
    return '<image class="bfm-badge-mark" href="' + src(key) + '" x="' + (cx - size / 2) +
      '" y="' + (cy - size / 2) + '" width="' + size + '" height="' + size +
      '" preserveAspectRatio="xMidYMid meet"/>';
  }

  // chess.com tints the squares of the graded move
  function squareTint(key, xy, size, strength) {
    return '<rect x="' + xy[0] + '" y="' + xy[1] + '" width="' + size + '" height="' + size +
      '" fill="' + color(key) + '" opacity="' + (strength || .5) + '"/>';
  }

  window.BFMIcons = { COLOR, DATA, color, src, img, disc, boardBadge, squareTint };
})();
